@pytest.mark.parametrize(
    "email,verified,expected",
    [
        ("tufts1cr@cmich.edu", True, True),
        ("person@CMICH.EDU", True, True),
        ("person@cmıch.edu", True, False),
        ("person@cmich.edu.evil.test", True, False),
        ("person@sub.cmich.edu", True, False),
        ("person@cmich.edu", False, False),
        ("person@cmich.edu", "true", False),
        ("a@b@cmich.edu", True, False),
    ],
)
def test_domain_requires_verified_exact_domain(email, verified, expected):
    assert (
        auth.allowed_identity({"email": email, "email_verified": verified}) is expected
    )


