def test_unauthenticated_api_and_csrf_blocked(auth_client):
    assert auth_client.get("/api/locations").status_code == 401
    assert (
        auth_client.post(
            "/api/messaging",
            json={"message": "x"},
            headers={"origin": "https://evil.test"},
        ).status_code
        == 403
    )
    assert auth_client.get("/api/auth/callback?state=bad&code=bad").status_code == 400


def test_pkce_binding_single_use_session_and_logout(auth_client, monkeypatch):
    from urllib.parse import parse_qs, urlparse

    response = auth_client.get("/api/auth/login", follow_redirects=False)
    query = parse_qs(urlparse(response.headers["location"]).query)
    assert query["code_challenge_method"] == ["S256"]
    assert (
        "HttpOnly" in response.headers["set-cookie"]
        and "Secure" in response.headers["set-cookie"]
    )
    nonce = query["nonce"][0]
    monkeypatch.setattr(
        auth.httpx,
        "post",
        lambda *a, **k: SimpleNamespace(
            raise_for_status=lambda: None,
            json=lambda: {"id_token": "id", "access_token": "access"},
        ),
    )
    monkeypatch.setattr(
        auth,
        "verify_token",
        lambda token, kind, cfg: {
            "sub": "user",
            "nonce": nonce,
            "email": "person@cmich.edu",
            "email_verified": True,
            "exp": int(time.time()) + 3600,
        },
    )
    url = "/api/auth/callback?state=" + query["state"][0] + "&code=code"
    # A callback without the browser-binding cookie cannot consume the state.
    with TestClient(app, base_url="https://cats.example") as other:
        assert other.get(url).status_code == 400
    assert auth_client.get(url, follow_redirects=False).status_code == 303
    assert auth_client.get(url).status_code == 400
    assert auth_client.get("/api/auth/session").json()["authenticated"]
    assert (
        auth_client.post(
            "/api/auth/logout", headers={"origin": "https://cats.example"}
        ).status_code
        == 200
    )
    assert not auth_client.get("/api/auth/session").json()["authenticated"]


def test_token_issuer_client_type_and_expiry(monkeypatch):
    key = rsa.generate_private_key(public_exponent=65537, key_size=2048)
    monkeypatch.setattr(
        auth,
        "jwks",
        lambda issuer: SimpleNamespace(
            get_signing_key_from_jwt=lambda token: SimpleNamespace(key=key.public_key())
        ),
    )
    cfg = {"issuer": "https://issuer.example", "client": "client"}
    claims = {
        "iss": cfg["issuer"],
        "client_id": "client",
        "sub": "user",
        "iat": int(time.time()),
        "exp": int(time.time()) + 300,
        "token_use": "access",
    }
    assert (
        auth.verify_token(jwt.encode(claims, key, algorithm="RS256"), "access", cfg)[
            "sub"
        ]
        == "user"
    )
    for change in (
        {"iss": "https://evil.test"},
        {"client_id": "other"},
        {"token_use": "id"},
        {"exp": 1},
    ):
        with pytest.raises((jwt.PyJWTError, ValueError)):
            auth.verify_token(
                jwt.encode(claims | change, key, algorithm="RS256"), "access", cfg
            )
